import javax.swing.JPanel;

/**
 * TASK: Move a marker around an 11x11 grid with the arrow keys.
 *
 * Register a KeyListener and handle keyPressed. Switch on e.getKeyCode():
 *   KeyEvent.VK_LEFT  -> x - 1        KeyEvent.VK_RIGHT -> x + 1
 *   KeyEvent.VK_UP    -> y - 1        KeyEvent.VK_DOWN  -> y + 1
 * Every other key is ignored.
 *
 * Both coordinates are CLAMPED to 0..10: they never go below 0 and never go
 * above 10. The marker starts in the middle at (5, 5).
 *
 * The readers are called posX() and posY() -- not getX()/getY(), because
 * JPanel already inherits those from java.awt.Component.
 *
 * Example: press LEFT, LEFT, UP
 *   posX() -> 3
 *   posY() -> 4
 *
 * No window is ever opened -- the tests build KeyEvents by hand and hand them
 * straight to the registered listener.
 */
public class ArrowMover extends JPanel {

    private int x = 5;
    private int y = 5;

    public ArrowMover() {
        // TODO: addKeyListener(...) so keyPressed moves x/y by 1 and clamps
        // both values to the range 0..10
    }

    public int posX() {
        // TODO: return the current column
        return 0;
    }

    public int posY() {
        // TODO: return the current row
        return 0;
    }
}

