import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class ArrowMoverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void press(ArrowMover panel, int keyCode) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_PRESSED,
                System.currentTimeMillis(), 0, keyCode, KeyEvent.CHAR_UNDEFINED);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyPressed(event);
        }
    }

    static void press(ArrowMover panel, int keyCode, int times) {
        for (int i = 0; i < times; i++) {
            press(panel, keyCode);
        }
    }

    static String pos(ArrowMover panel) {
        return panel.posX() + "," + panel.posY();
    }

    public static void main(String[] args) {
        try {
            ArrowMover panel = new ArrowMover();
            check("a KeyListener is registered", true, panel.getKeyListeners().length >= 1);
            check("starts in the middle", "5,5", pos(panel));

            press(panel, KeyEvent.VK_LEFT);
            press(panel, KeyEvent.VK_UP);
            check("after LEFT then UP", "4,4", pos(panel));

            press(panel, KeyEvent.VK_A);
            check("a letter key is ignored", "4,4", pos(panel));

            press(panel, KeyEvent.VK_LEFT, 9);
            check("x clamps at 0", "0,4", pos(panel));

            press(panel, KeyEvent.VK_RIGHT, 20);
            check("x clamps at 10", "10,4", pos(panel));

            press(panel, KeyEvent.VK_DOWN, 12);
            check("y clamps at 10", "10,10", pos(panel));

            press(panel, KeyEvent.VK_UP, 3);
            check("after three UPs", "10,7", pos(panel));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

