import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import javax.swing.JPanel;

public class ArrowMover extends JPanel {

    private int x = 5;
    private int y = 5;

    public ArrowMover() {
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_LEFT:
                        x = clamp(x - 1);
                        break;
                    case KeyEvent.VK_RIGHT:
                        x = clamp(x + 1);
                        break;
                    case KeyEvent.VK_UP:
                        y = clamp(y - 1);
                        break;
                    case KeyEvent.VK_DOWN:
                        y = clamp(y + 1);
                        break;
                    default:
                        break;
                }
            }
        });
    }

    private static int clamp(int value) {
        if (value < 0) {
            return 0;
        }
        if (value > 10) {
            return 10;
        }
        return value;
    }

    public int posX() {
        return x;
    }

    public int posY() {
        return y;
    }
}
